'use client'

import { useRef, useMemo, useEffect, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { Bloom, EffectComposer } from '@react-three/postprocessing'
import * as THREE from 'three'
import type {
  AtmosphereProps,
  HeroSceneProps,
  LayerDef,
  MotionProps,
  PhotoLayerProps,
} from '@/types/hero-scene'


const BG = '#10131f' // deep navy space — matches the .theme-navy background
const INK = new THREE.Color('#cfd6e6')
const AMBER = new THREE.Color('#e0a050')
const WARM = new THREE.Color('#f3ddb4') // soft warm light
const BLOOM_INK = new THREE.Color('#e7f0ff').multiplyScalar(1.85)
const BLOOM_AMBER = new THREE.Color('#ffd08a').multiplyScalar(2.35)
const BLOOM_WARM = new THREE.Color('#ffe0a8').multiplyScalar(2.15)

// Camera still travels deep through the photo corridor; the Hero shell is what
// stays sticky, not the camera motion itself.
const CAM_START = 5.8
const CAM_END = -14.5
const OPENING_PHOTO_PRESENCE = 0.38

/* ---------- canvas helpers ---------- */

function roundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  ctx.beginPath()
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + w, y, x + w, y + h, r)
  ctx.arcTo(x + w, y + h, x, y + h, r)
  ctx.arcTo(x, y + h, x, y, r)
  ctx.arcTo(x, y, x + w, y, r)
  ctx.closePath()
}

// Composite a single real photo into a floating "layer": rounded corners, a
// thin warm frame, a soft bottom vignette and a minimal label. No browser
// chrome, no buttons — the photograph itself is the subject.
function makePhotoTexture(
  img: HTMLImageElement | null,
  label: string,
  ar: number, // width / height of the card
) {
  const H = 768
  const W = Math.round(H * ar)
  const c = document.createElement('canvas')
  c.width = W
  c.height = H
  const ctx = c.getContext('2d')!
  const r = 26

  // clip to a rounded rect so the layer has soft corners (outside stays transparent)
  ctx.save()
  roundRect(ctx, 6, 6, W - 12, H - 12, r)
  ctx.clip()

  if (img) {
    // cover-fit the photo
    const ir = img.width / img.height
    const tr = W / H
    let dw = W
    let dh = H
    let dx = 0
    let dy = 0
    if (ir > tr) {
      dh = H
      dw = H * ir
      dx = (W - dw) / 2
    } else {
      dw = W
      dh = W / ir
      dy = (H - dh) / 2
    }
    ctx.drawImage(img, dx, dy, dw, dh)
  } else {
    ctx.fillStyle = '#1c2233'
    ctx.fillRect(0, 0, W, H)
  }

  // gentle bottom-to-top vignette for label legibility + depth
  const g = ctx.createLinearGradient(0, H * 0.5, 0, H)
  g.addColorStop(0, 'rgba(12,15,24,0)')
  g.addColorStop(1, 'rgba(12,15,24,0.62)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, W, H)

  // minimal label: a short accent tick + small text, low-key
  ctx.fillStyle = '#e6b066'
  ctx.fillRect(40, H - 86, 34, 3)
  ctx.fillStyle = 'rgba(247,243,236,0.92)'
  ctx.font = '500 30px ui-sans-serif, system-ui, sans-serif'
  ctx.textBaseline = 'alphabetic'
  ctx.fillText(label, 40, H - 50)

  ctx.restore()

  // thin warm frame on top of the rounded edge
  roundRect(ctx, 6, 6, W - 12, H - 12, r)
  ctx.strokeStyle = 'rgba(243,221,180,0.16)'
  ctx.lineWidth = 2
  ctx.stroke()

  const tex = new THREE.CanvasTexture(c)
  tex.anisotropy = 8
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

// soft radial glow sprite for atmospheric light/haze
function makeGlowTexture() {
  const S = 256
  const c = document.createElement('canvas')
  c.width = S
  c.height = S
  const ctx = c.getContext('2d')!
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.4, 'rgba(255,255,255,0.5)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, S, S)
  return new THREE.CanvasTexture(c)
}

function makeCloudTexture() {
  const S = 512
  const c = document.createElement('canvas')
  c.width = S
  c.height = S
  const ctx = c.getContext('2d')!

  for (let i = 0; i < 58; i++) {
    const x = S * (0.16 + Math.random() * 0.68)
    const y = S * (0.24 + Math.random() * 0.52)
    const r = S * (0.07 + Math.random() * 0.13)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, `rgba(255,255,255,${0.24 + Math.random() * 0.2})`)
    g.addColorStop(0.48, `rgba(255,255,255,${0.16 + Math.random() * 0.12})`)
    g.addColorStop(0.74, 'rgba(255,255,255,0.04)')
    g.addColorStop(1, 'rgba(255,255,255,0)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, S, S)
  }

  ctx.globalCompositeOperation = 'destination-in'
  const mask = ctx.createRadialGradient(S / 2, S / 2, S * 0.12, S / 2, S / 2, S * 0.46)
  mask.addColorStop(0, 'rgba(255,255,255,1)')
  mask.addColorStop(0.64, 'rgba(255,255,255,0.96)')
  mask.addColorStop(0.84, 'rgba(255,255,255,0.34)')
  mask.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = mask
  ctx.fillRect(0, 0, S, S)
  ctx.globalCompositeOperation = 'source-over'

  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

/* ---------- the floating photo layers ---------- */

// A composed corridor that recedes into depth. The left edge is kept clear for
// the headline (photos sit center → right, sweeping further aside as you pass).
// Photos are NOT scattered: z steps back steadily so it reads as a path you
// travel down. Each layer's `sweep` pushes it off-screen on the side it already
// leans toward, so the camera glides *between* them instead of clipping through.
const LAYERS: LayerDef[] = [
  // foreground — restaurant, just right of center, passed first
  { photo: '/jp/cafe.png', label: '飲食 / Restaurant', pos: [2.0, 0.1, -0.5], rotY: -0.18, rotX: 0.02, h: 3.2, ar: 1.5, drift: 0.1, sweep: [3.6, -0.6] },
  // salon, upper right
  { photo: '/jp/salon.png', label: '美容 / Salon', pos: [4.6, 1.7, -2.6], rotY: -0.28, rotX: 0.0, h: 2.8, ar: 0.78, drift: 0.14, sweep: [4.2, 1.6] },
  // workshop, lower center-right
  { photo: '/jp/craft.png', label: 'ものづくり / Craft', pos: [-2.4, -1.6, -4.2], rotY: 0.2, rotX: 0.05, h: 2.6, ar: 1.4, drift: 0.14, sweep: [-4.0, -1.8] },
  // clinic, mid-right, deeper
  { photo: '/jp/clinic.png', label: '医療 / Clinic', pos: [3.6, -0.6, -6.4], rotY: -0.26, rotX: 0.0, h: 2.6, ar: 1.45, drift: 0.16, sweep: [4.0, -1.4] },
  // izakaya / store, upper, deeper
  { photo: '/jp/store.png', label: '店舗 / Store', pos: [-2.2, 1.8, -8.4], rotY: 0.14, rotX: 0.02, h: 2.5, ar: 1.5, drift: 0.18, sweep: [-3.8, 2.0] },
  // farm, center, deep
  { photo: '/jp/farm.png', label: '農業 / Agriculture', pos: [2.4, -1.0, -10.6], rotY: -0.16, rotX: 0.03, h: 2.4, ar: 1.5, drift: 0.2, sweep: [3.4, -1.6] },
  // photographer / personal brand, deepest — the last one you break past
  { photo: '/jp/personal.png', label: '個人ブランド / Creator', pos: [-1.2, 0.6, -12.8], rotY: 0.1, rotX: 0.0, h: 2.2, ar: 1.3, drift: 0.22, sweep: [-3.0, 1.2] },
]

function smoothstep(edge0: number, edge1: number, x: number) {
  const t = THREE.MathUtils.clamp((x - edge0) / (edge1 - edge0), 0, 1)
  return t * t * (3 - 2 * t)
}

function PhotoLayer({
  def,
  texture,
  progress,
  reduced,
}: PhotoLayerProps) {
  const group = useRef<THREE.Group>(null)
  const mat = useRef<THREE.MeshBasicMaterial>(null)
  const { camera } = useThree()
  const phase = useMemo(() => Math.random() * Math.PI * 2, [])

  useFrame((state, delta) => {
    const g = group.current
    const m = mat.current
    if (!g || !m) return

    const camZ = camera.position.z
    // how far the layer sits AHEAD of the camera (>0 in front, <0 once passed)
    const ahead = camZ - def.pos[2]

    // 1) reveal out of the fog as the camera gets within range.
    // Keep a faint establishing view in the FV; otherwise most photos are fully
    // transparent until the first scroll movement, which makes the hero feel empty.
    const reveal = smoothstep(15, 9.5, ahead) // 0 when far (>=15), 1 by 9.5
    const opening = (1 - smoothstep(0.04, 0.28, progress.current)) * smoothstep(24, 12, ahead)
    const presence = Math.max(reveal, opening * OPENING_PHOTO_PRESENCE)
    // 2) as the camera arrives (ahead → 0) sweep the layer aside and fade it
    //    out so you pass BETWEEN photos rather than clip through them
    const pass = reduced ? 0 : smoothstep(3.2, -0.6, ahead) // 0 far, 1 at/behind
    const passFade = smoothstep(-1.2, 1.6, ahead) // fades to 0 just after passing
    const baseTex = texture ? 1 : 0

    m.opacity += (baseTex * presence * passFade - m.opacity) * Math.min(1, delta * 4)

    // idle float keeps the resting space alive (small, organic — not UI motion)
    const t = state.clock.elapsedTime
    const fx = reduced ? 0 : Math.cos(t * 0.3 + phase) * def.drift * 0.5
    const fy = reduced ? 0 : Math.sin(t * 0.4 + phase) * def.drift

    // ease3: extra forward nudge so deep layers visibly approach before passing
    const approach = (1 - presence) * -1.2

    g.position.x = def.pos[0] + def.sweep[0] * pass + fx
    g.position.y = def.pos[1] + def.sweep[1] * pass + fy
    g.position.z = def.pos[2] + approach
    // a touch of yaw as it sweeps past, reinforcing the "moving by" feel
    g.rotation.y = def.rotY - def.sweep[0] * 0.04 * pass
    g.rotation.x = def.rotX
  })

  return (
    <group ref={group} position={def.pos} rotation={[def.rotX, def.rotY, 0]}>
      <mesh scale={[def.h * def.ar, def.h, 1]}>
        <planeGeometry args={[1, 1]} />
        <meshBasicMaterial
          ref={mat}
          map={texture ?? undefined}
          transparent
          opacity={0}
          toneMapped={false}
          side={THREE.DoubleSide}
        />
      </mesh>
    </group>
  )
}

/* ---------- depth motes that stream toward the camera (speed cue) ---------- */

function Motes({
  progress,
  glow,
  reduced,
}: MotionProps & {
  glow: THREE.Texture
}) {
  const ref = useRef<THREE.InstancedMesh>(null)
  const bloom = useRef<THREE.InstancedMesh>(null)
  const count = 260
  const dummy = useMemo(() => new THREE.Object3D(), [])
  const glowDummy = useMemo(() => new THREE.Object3D(), [])
  const data = useMemo(() => {
    const arr: {
      x: number
      y: number
      z: number
      s: number
      speed: number
      phase: number
      amber: boolean
    }[] = []
    for (let i = 0; i < count; i++) {
      arr.push({
        x: (Math.random() - 0.5) * 18,
        y: (Math.random() - 0.5) * 11,
        z: CAM_START - Math.random() * 32,
        s: 0.018 + Math.random() * 0.055,
        speed: 0.65 + Math.random() * 1.35,
        phase: Math.random() * Math.PI * 2,
        amber: Math.random() < 0.28,
      })
    }
    return arr
  }, [])

  useEffect(() => {
    const mesh = ref.current
    const glow = bloom.current
    if (!mesh || !glow) return
    const col = new THREE.Color()
    data.forEach((d, i) => {
      dummy.position.set(d.x, d.y, d.z)
      dummy.scale.setScalar(d.s)
      dummy.updateMatrix()
      mesh.setMatrixAt(i, dummy.matrix)

      glowDummy.position.set(d.x, d.y, d.z)
      glowDummy.scale.setScalar(d.s * 2.8)
      glowDummy.updateMatrix()
      glow.setMatrixAt(i, glowDummy.matrix)

      col.copy(d.amber ? BLOOM_AMBER : BLOOM_INK)
      mesh.setColorAt(i, col)
      glow.setColorAt(i, col)
    })
    mesh.instanceMatrix.needsUpdate = true
    glow.instanceMatrix.needsUpdate = true
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
    if (glow.instanceColor) glow.instanceColor.needsUpdate = true
  }, [data, dummy, glowDummy])

  useFrame((state, delta) => {
    const mesh = ref.current
    const glow = bloom.current
    if (!mesh || !glow) return
    const camZ = state.camera.position.z
    const farZ = camZ - 34
    const nearZ = camZ + 2.8
    // A constant stream from the far corridor, with extra velocity while the
    // camera is flying forward through the photos.
    const stream = reduced ? 0.35 : 1.2 + progress.current * 4.2
    let changed = false
    data.forEach((d, i) => {
      d.z += delta * stream * d.speed
      // recycle motes that pass the viewer back to the far depth, so new
      // particles keep welling up from behind the photo corridor.
      if (d.z > nearZ) {
        d.z = farZ - Math.random() * 8
        d.x = (Math.random() - 0.5) * 18
        d.y = (Math.random() - 0.5) * 11
        d.s = 0.018 + Math.random() * 0.055
        d.speed = 0.65 + Math.random() * 1.35
        changed = true
      }
      const depth = THREE.MathUtils.clamp((d.z - farZ) / (nearZ - farZ), 0, 1)
      const t = state.clock.elapsedTime
      const drift = reduced ? 0 : Math.sin(t * 0.5 + d.phase) * 0.08

      dummy.position.set(d.x + drift * depth, d.y - drift * 0.55 * depth, d.z)
      const scale = d.s * (0.45 + depth * 2.65)
      dummy.scale.setScalar(scale)
      dummy.updateMatrix()
      mesh.setMatrixAt(i, dummy.matrix)

      glowDummy.position.copy(dummy.position)
      glowDummy.scale.setScalar(scale * (2.8 + depth * 2.6))
      glowDummy.updateMatrix()
      glow.setMatrixAt(i, glowDummy.matrix)
    })
    mesh.instanceMatrix.needsUpdate = true
    glow.instanceMatrix.needsUpdate = true
    if (changed && mesh.instanceColor) mesh.instanceColor.needsUpdate = true
    if (changed && glow.instanceColor) glow.instanceColor.needsUpdate = true
  })

  return (
    <>
      <instancedMesh ref={bloom} args={[undefined, undefined, count]}>
        <planeGeometry args={[1, 1]} />
        <meshBasicMaterial
          map={glow}
          transparent
          opacity={0.82}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh ref={ref} args={[undefined, undefined, count]}>
        <circleGeometry args={[1, 12]} />
        <meshBasicMaterial
          transparent
          opacity={0.95}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
    </>
  )
}

function CloudField({
  texture,
  progress,
  reduced,
}: {
  texture: THREE.Texture
  progress: MotionProps['progress']
  reduced: boolean
}) {
  const group = useRef<THREE.Group>(null)
  const clouds = useMemo(() => {
    return Array.from({ length: 9 }, () => ({
      x: -14 + Math.random() * 28,
      y: -4.2 + Math.random() * 8.4,
      z: CAM_START - 10 - Math.random() * 30,
      speed: 0.018 + Math.random() * 0.036,
      stream: 0.22 + Math.random() * 0.46,
      phase: Math.random() * Math.PI * 2,
      layers: Array.from({ length: 7 + Math.round(Math.random() * 9) }, () => ({
        x: (Math.random() - 0.5) * 4.8,
        y: (Math.random() - 0.5) * 2.4,
        z: (Math.random() - 0.5) * 3.2,
        scale: 1.8 + Math.random() * 3.2,
        aspect: 1.65 + Math.random() * 1.4,
        angle: Math.random() * Math.PI * 2,
        spin: (0.018 + Math.random() * 0.06) * (Math.random() > 0.5 ? 1 : -1),
        opacity: 0.09 + Math.random() * 0.14,
      })),
    }))
  }, [])

  useFrame(({ clock, camera }, delta) => {
    const g = group.current
    if (!g) return
    const time = clock.elapsedTime
    const farZ = camera.position.z - 42
    const nearZ = camera.position.z + 5
    g.children.forEach((child, i) => {
      const cloud = clouds[i]
      const cluster = child as THREE.Group
      const driftSpeed = reduced ? cloud.speed * 0.28 : cloud.speed
      const streamSpeed = reduced ? cloud.stream * 0.2 : cloud.stream * (0.8 + progress.current * 1.4)

      cluster.position.x += delta * driftSpeed
      cluster.position.z += delta * streamSpeed
      if (cluster.position.x > 14) {
        cluster.position.x = -14 - Math.random() * 5
        cluster.position.y = -4.2 + Math.random() * 8.4
      }
      if (cluster.position.z > nearZ) {
        cluster.position.x = -14 + Math.random() * 28
        cluster.position.y = -4.2 + Math.random() * 8.4
        cluster.position.z = farZ - Math.random() * 12
      }

      cluster.position.y = cloud.y + Math.sin(time * 0.08 + cloud.phase) * 0.42
      cluster.rotation.y = Math.sin(time * 0.035 + cloud.phase) * 0.08
      const depth = THREE.MathUtils.clamp((cluster.position.z - farZ) / (nearZ - farZ), 0, 1)
      const depthFade = smoothstep(0.02, 0.24, depth) * (1 - smoothstep(0.82, 1, depth))

      cluster.children.forEach((layerChild, j) => {
        const layer = cloud.layers[j]
        const mesh = layerChild as THREE.Mesh
        const mat = mesh.material as THREE.MeshBasicMaterial
        mesh.quaternion.copy(camera.quaternion)
        mesh.rotateZ(layer.angle + time * (reduced ? layer.spin * 0.2 : layer.spin))
        mat.opacity =
          layer.opacity *
          depthFade *
          (0.82 + Math.sin(time * 0.13 + cloud.phase + j) * 0.18)
      })
    })
  })

  return (
    <group ref={group}>
      {clouds.map((cloud, i) => (
        <group key={i} position={[cloud.x, cloud.y, cloud.z]}>
          {cloud.layers.map((layer, j) => (
            <mesh
              key={j}
              position={[layer.x, layer.y, layer.z]}
              rotation={[0, 0, layer.angle]}
              scale={[layer.scale * layer.aspect, layer.scale, 1]}
            >
              <planeGeometry args={[1, 1]} />
              <meshBasicMaterial
                map={texture}
                transparent
                opacity={layer.opacity}
                depthWrite={false}
                blending={THREE.NormalBlending}
                color={INK}
                toneMapped={false}
              />
            </mesh>
          ))}
        </group>
      ))}
    </group>
  )
}

/* ---------- camera rig: scroll = forward flight, mouse = gaze ---------- */

function Rig({
  progress,
  reduced,
}: MotionProps) {
  const { camera } = useThree()
  const mouse = useRef({ x: 0, y: 0 })
  const target = useRef({ x: 0, y: 0 })

  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      target.current.x = (e.clientX / window.innerWidth) * 2 - 1
      target.current.y = (e.clientY / window.innerHeight) * 2 - 1
    }
    window.addEventListener('pointermove', onMove)
    return () => window.removeEventListener('pointermove', onMove)
  }, [])

  useFrame((state, delta) => {
    const k = Math.min(1, delta * 3)
    const p = progress.current

    // gentle auto-sway so the gaze lives on touch devices too
    const t = state.clock.elapsedTime
    const autoX = Math.sin(t * 0.18) * 0.12
    const autoY = Math.cos(t * 0.15) * 0.08
    mouse.current.x += (target.current.x + autoX - mouse.current.x) * k
    mouse.current.y += (target.current.y + autoY - mouse.current.y) * k

    // FORWARD FLIGHT: scroll drives the camera deep through the corridor.
    // Reduced motion only creeps forward a little.
    const z = reduced
      ? CAM_START - p * 2.5
      : CAM_START + (CAM_END - CAM_START) * p
    camera.position.z += (z - camera.position.z) * k

    // keep a slight rightward bias so the photo path stays in frame while the
    // left stays open for the headline; mouse adds a small parallax gaze
    const sway = reduced ? 0.25 : 1
    const baseX = 0.6 // gentle offset toward the corridor
    camera.position.x += (baseX + mouse.current.x * 0.7 * sway - camera.position.x) * k
    camera.position.y += (-mouse.current.y * 0.45 * sway - camera.position.y) * k
    camera.rotation.y += (-mouse.current.x * 0.05 - camera.rotation.y) * k
    camera.rotation.x += (mouse.current.y * 0.03 - camera.rotation.x) * k
  })

  return null
}

/* ---------- atmospheric light ---------- */

function Atmosphere({
  progress,
  glow,
}: AtmosphereProps) {
  const warmMat = useRef<THREE.MeshBasicMaterial>(null)
  const warm = useRef<THREE.Group>(null)
  useFrame(({ camera }) => {
    const p = progress.current
    // the open space of light lives near the end of the corridor and blooms as
    // you break through the last photo layer
    if (warmMat.current) warmMat.current.opacity = 0.3 + smoothstep(0.5, 1, p) * 0.55
    if (warm.current) {
      // keep the glow a little ahead of the camera so we "arrive" into it
      warm.current.position.z = Math.min(-13, camera.position.z - 4)
    }
  })
  return (
    <group>
      <group ref={warm}>
        <mesh position={[1, 0.3, 0]} scale={[42, 30, 1]}>
          <planeGeometry args={[1, 1]} />
          <meshBasicMaterial
            ref={warmMat}
            map={glow}
            transparent
            depthWrite={false}
            color={BLOOM_WARM}
            toneMapped={false}
          />
        </mesh>
      </group>
      <mesh position={[-6, 3, -9]} scale={[16, 14, 1]}>
        <planeGeometry args={[1, 1]} />
        <meshBasicMaterial
          map={glow}
          transparent
          opacity={0.18}
          depthWrite={false}
          color={BLOOM_AMBER}
          toneMapped={false}
        />
      </mesh>
    </group>
  )
}

function Scene({
  progress,
  reduced,
}: MotionProps) {
  const glow = useMemo(() => makeGlowTexture(), [])
  const cloud = useMemo(() => makeCloudTexture(), [])
  const [textures, setTextures] = useState<Record<number, THREE.Texture>>({})

  // load each layer's photo and composite it into a floating photo texture
  useEffect(() => {
    let alive = true
    const made: THREE.Texture[] = []
    LAYERS.forEach((def, i) => {
      const img = new Image()
      img.crossOrigin = 'anonymous'
      img.src = def.photo
      const build = (image: HTMLImageElement | null) => {
        if (!alive) return
        const tex = makePhotoTexture(image, def.label, def.ar)
        made.push(tex)
        setTextures((prev) => ({ ...prev, [i]: tex }))
      }
      img.onload = () => build(img)
      img.onerror = () => build(null)
    })
    return () => {
      alive = false
      made.forEach((t) => t.dispose())
    }
  }, [])

  useEffect(
    () => () => {
      glow.dispose()
      cloud.dispose()
    },
    [cloud, glow],
  )

  return (
    <>
      <color attach="background" args={[BG]} />
      <fog attach="fog" args={[BG, 6, 22]} />
      <Atmosphere progress={progress} glow={glow} />
      <CloudField texture={cloud} progress={progress} reduced={reduced} />
      <Motes progress={progress} glow={glow} reduced={reduced} />
      {LAYERS.map((def, i) => (
        <PhotoLayer
          key={i}
          def={def}
          texture={textures[i] ?? null}
          progress={progress}
          reduced={reduced}
        />
      ))}
      <Rig progress={progress} reduced={reduced} />
    </>
  )
}

export function HeroScene({
  progress,
  reduced = false,
}: HeroSceneProps) {
  return (
    <Canvas
      gl={{ antialias: true, powerPreference: 'high-performance' }}
      dpr={[1, 2]}
      camera={{ position: [0.6, 0, CAM_START], fov: 50 }}
    >
      <Scene progress={progress} reduced={reduced} />
      {!reduced && (
        <EffectComposer>
          <Bloom
            intensity={0.95}
            luminanceThreshold={0.22}
            luminanceSmoothing={0.36}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  )
}
